void WorldArt::set_mesh(u32& slot, const MeshData& mesh, const Material& m) {
  if (mesh.vertex_count() == 0) {
    if (slot) r_->remove(slot);
    slot = 0;
    return;
  }
  MeshLook look;
  look.material = m;
  if (!slot) slot = r_->allocate_id();
  if (!upsert(*r_, slot, mesh, look)) { r_->release_id(slot); slot = 0; }
}
void WorldArt::put(PartId id, const Mat4& m, Vec3 tint) {
  if (id == 0 || id >= parts_.size()) return;
  Part& p = converted::at(parts_, id);
  p.transforms.insert(p.transforms.end(), m.m, m.m + 16);
  if (p.tinted) p.tints.insert(p.tints.end(), {tint.x, tint.y, tint.z, 1});
}
namespace terrain_cpp_local { u64 key2(i32 i, i32 j) { return (converted::shl_bits(static_cast<u64>(static_cast<u32>(i)), 32)) | static_cast<u32>(j); } }
f32 crater_profile(f32 r, f32 radius, f32 depth, f32 rim) {
  const f32 bowl = radius * 0.5;
  if (r < bowl) return -depth * (1 - (r / bowl) * (r / bowl));
  if (r >= radius) return 0;
  const f32 x = (r - bowl) / (radius - bowl), k = (x - 0.12) / 0.14;
  return rim * kern::math::exp(-(k * k)) * (1 - x);
}
namespace terrain_cpp_local { Vec4 interior_of(f32 x0, f32 y0, f32 span, f32 margin) { return {x0 + margin, y0 + margin, x0 + span - margin, y0 + span - margin}; } }
Vec4 Terrain::interior(const Grid& g) const {
  return terrain_cpp_local::interior_of(g.x0, g.y0, g.step * static_cast<f32>(g.n > 0 ? g.n - 1 : 0), kDemMargin);
}
f32 Terrain::grid_at(const Grid& g, f32 x, f32 y) const {
  if (g.n < 2) return 0;
  const f32 lim = static_cast<f32>(g.n) - 1.001;
  const f32 fx = clampf((x - g.x0) / g.step, 0, lim), fy = clampf((y - g.y0) / g.step, 0, lim);
  const u32 i = static_cast<u32>(converted::fits<unsigned int>(fx)), j = static_cast<u32>(converted::fits<unsigned int>(fy));
  const f32 tx = fx - i, ty = fy - j;
  const std::size_t at = converted::plus(converted::times(static_cast<std::size_t>(j), g.n), i);
  return (converted::at(g.h, at) * (1 - tx) + converted::at(g.h, converted::plus(at, 1)) * tx) * (1 - ty) + (converted::at(g.h, converted::plus(at, g.n)) * (1 - tx) + converted::at(g.h, converted::plus(converted::plus(at, g.n), 1)) * tx) * ty;
}
f32 Terrain::elevation(f32 x, f32 y) const {
  if (!grid_ready_) return 0.0;
  // the window that knows the place (its interior); else any that holds it; else the player's,
  // held at its edge (far ground nobody stands on: the horizon)
  auto in = [&](const Vec4& r) { return x >= r.x && y >= r.y && x <= r.z && y <= r.w; };
  if (side_.empty() || in(interior(grid_))) return grid_at(grid_, x, y) - ref_height_;
  for (const Grid& g : side_) if (in(interior(g))) return grid_at(g, x, y) - ref_height_;
  if (in(terrain_cpp_local::interior_of(grid_.x0, grid_.y0, grid_.step * static_cast<f32>(grid_.n - 1), 0))) return grid_at(grid_, x, y) - ref_height_;
  for (const Grid& g : side_) if (in(terrain_cpp_local::interior_of(g.x0, g.y0, g.step * static_cast<f32>(g.n - 1), 0))) return grid_at(g, x, y) - ref_height_;
  return grid_at(grid_, x, y) - ref_height_;
}
namespace terrain_cpp_local { constexpr f32 kRoadGrid = 24, kRoadBlend = 4.5; }
namespace terrain_cpp_local { u64 road_key(i32 ix, i32 iy) { return (converted::shl_bits(static_cast<u64>(static_cast<u32>(ix)), 32)) | static_cast<u32>(iy); } }
i32 Terrain::corridor_set(f32 x, f32 y) const {
  // the map tile whose square holds the point (the squares tile the plane: west / south edge in - one at most)
  for (std::size_t i = 0; i < corridors_.size(); converted::pre_inc(i)) {
    const CorridorSet& s = *converted::present(converted::at(corridors_, i));
    if (x >= s.bounds.x && x < s.bounds.z && y >= s.bounds.y && y < s.bounds.w) return static_cast<i32>(i);
  }
  return -1;
}
f32 Terrain::road_level(f32 x, f32 y, f32 h) const {
  // terrain_craters.mjs roadLevel: every corridor covering the point contributes (weighted), so
  // junctions blend smoothly, no steps
  const i32 at = corridors_.empty() ? -1 : corridor_set(x, y);
  if (at < 0) return h;
  const CorridorSet& set = *converted::present(converted::at(corridors_, static_cast<std::size_t>(at)));
  const auto it = set.grid.find(terrain_cpp_local::road_key(static_cast<i32>(converted::fits<int>(std::floor(x / terrain_cpp_local::kRoadGrid))), static_cast<i32>(converted::fits<int>(std::floor(y / terrain_cpp_local::kRoadGrid)))));
  if (it == set.grid.end()) return h;
  f32 best = 0, sw = 0, sh = 0;
  for (const CorridorSeg& s : it->second) {
    const f32 t = clampf(((x - s.ax) * s.dx + (y - s.ay) * s.dy) / s.l2, 0, 1);
    const f32 px = s.ax + s.dx * t, py = s.ay + s.dy * t, d = hypot_bp(x - px, y - py);
    const f32 w = d <= s.half ? 1 : d >= s.half + terrain_cpp_local::kRoadBlend ? 0 : 1 - (d - s.half) / terrain_cpp_local::kRoadBlend;
    if (w <= 0) continue;
    const f32 ws = w * w * (3 - 2 * w);
    sw += ws;
    sh += ws * (s.ha + (s.hb - s.ha) * t);
    best = std::fmax(best, w);
  }
  if (sw <= 0) return h;
  return h + (sh / sw - h) * (best * best * (3 - 2 * best));
}
f32 Terrain::node_height(f32 x, f32 y) const {
  const f32 e = elevation(x, y);
  f32 h = road_level(x, y, e);
  for (const Crater& c : craters_) {
    const f32 dx = x - c.c.x, dy = y - c.c.y;
    if (std::fabs(dx) >= c.r || std::fabs(dy) >= c.r) continue;
    const f32 r = kern::math::sqrt(dx * dx + dy * dy);
    if (r < c.r) h += crater_profile(r, c.r, c.depth, c.rim);
  }
  if (!water_.empty() && water_at(x, y)) return std::fmin(h, e - kWaterBed);
  return h;
}
f32 Terrain::height(f32 x, f32 y) const {
  // terrain_surface.mjs triangleHeightAt: the SW-NE diagonal of every 5 m cell.
  const f32 x0 = std::floor(x / kStep) * kStep, y0 = std::floor(y / kStep) * kStep;
  const f32 u = (x - x0) / kStep, v = (y - y0) / kStep;
  const f32 a = node_height(x0, y0), d = node_height(x0 + kStep, y0 + kStep);
  return u >= v ? a + (node_height(x0 + kStep, y0) - a) * (u - v) + (d - a) * v : a + (node_height(x0, y0 + kStep) - a) * (v - u) + (d - a) * u;
}
bool Terrain::water_cell(i32 cx, i32 cy) const {
  // the 256 bits of the cell's 64 m block
  auto it = water_.find(terrain_cpp_local::key2(cx >> 4, cy >> 4));
  if (it == water_.end()) return false;
  const u32 idx = static_cast<u32>((cy & 15) * 16 + (cx & 15));
  return (converted::shr_bits(converted::at(it->second.bits, idx >> 6), (idx & 63))) & 1u;
}
bool Terrain::on_bridge(f32 x, f32 y) const {
  for (const Bridge& b : bridges_) {
    const f32 dx = x - b.c.x, dy = y - b.c.y;
    if (std::fabs(dx) > b.hl + b.hw || std::fabs(dy) > b.hl + b.hw) continue;
    const f32 c = kern::math::cos(b.yaw), s = kern::math::sin(b.yaw), u = dx * c + dy * s, v = -dx * s + dy * c;
    if (std::fabs(u) <= b.hl && std::fabs(v) <= b.hw) return true;
  }
  return false;
}
bool Terrain::water_at(f32 x, f32 y) const {
  if (water_.empty()) return false;
  if (!water_cell(static_cast<i32>(converted::fits<int>(std::floor(x / kWaterCell))), static_cast<i32>(converted::fits<int>(std::floor(y / kWaterCell))))) return false;
  return bridges_.empty() || !on_bridge(x, y);
}
constexpr u32 kScorches = 40, kSoots = 48, kBreaches = 64, kRubble = 36;
constexpr f32 kRubbleSeconds = 25;
const Vec3 kRubbleColor = converted::wide::hex_color(0x8a857c);
f32 ragged(f32 a, f32 seed) { return 0.74 + 0.13 * kern::math::sin(a * 5 + seed * 7) + 0.08 * kern::math::sin(a * 11 + seed * 3) + 0.05 * kern::math::sin(a * 23 + seed); }
void Marks::clear(World* w) {
  if (w)
    for (Chunk& c : rubble_)
      if (c.body.valid() && w->body_valid(c.body)) w->destroy_body(c.body);
  rubble_.clear();
  scorches_.clear();
  soots_.clear();
  breaches_.clear();
  cracks_.clear();
  crack_cursor_ = 0;
  scorch_cursor_ = soot_cursor_ = breach_cursor_ = rubble_cursor_ = 0;
  dirty_ = true;
  stats_ = {};
}
void Marks::spawn_rubble(Vec3 at, Vec2 n, i32 count, World& w, Rng& rng, f32 now) {
  for (i32 k = 0; k < count; ++k) {
    // facade_marks.mjs spawnRubble: concrete chunks (2400 kg/m^3), thrown out of the wall
    const Vec3 half{0.06 + rng.unit() * 0.12, 0.06 + rng.unit() * 0.1, 0.05 + rng.unit() * 0.08};
    physics::BodySettings bs;
    bs.type = physics::BodyType::dynamic;
    bs.position = at + Vec3{(rng.unit() - 0.5) * 0.8, (rng.unit() - 0.5) * 0.8, (rng.unit() - 0.5) * 0.8};
    bs.rotation = Quat::axis_angle({0, 0, 1}, rng.unit() * 6.28);
    const f32 sp = 3 + rng.unit() * 6;
    bs.linear_velocity = {n.x * sp + (rng.unit() - 0.5) * 3, n.y * sp + (rng.unit() - 0.5) * 3, 1 + rng.unit() * 4};
    bs.angular_velocity = {(rng.unit() - 0.5) * 12, (rng.unit() - 0.5) * 12, (rng.unit() - 0.5) * 12};
    bs.linear_damping = 0.05;
    bs.angular_damping = 0.2;
    const physics::Body b = w.create_body(bs);
    physics::ShapeSettings ss;
    ss.kind = physics::ShapeKind::box;
    ss.size = half * 2.0;
    ss.material.density = 2400;
    ss.material.friction = 0.8;
    ss.material.category_bits = kCatVehicle;  // debris: not a wall for the walkers' rays
    w.create_shape(b, ss);
    Chunk c{b, half, now + kRubbleSeconds};
    if (rubble_.size() < kRubble) rubble_.push_back(c);
    else {
      // full: the oldest chunk (the soonest to expire) makes room
      std::size_t oldest = 0;
      for (std::size_t i = 0; i < rubble_.size(); converted::pre_inc(i)) if (converted::at(rubble_, i).until < converted::at(rubble_, oldest).until) oldest = i;
      Chunk& old = converted::at(rubble_, oldest);
      if (old.body.valid() && w.body_valid(old.body)) w.destroy_body(old.body);
      old = c;
    }
  }
}
f32 fh(f32 n) { const f32 v = kern::math::sin(n * 127.1) * 43758.5453; return v - std::floor(v); }
bool facade_glass(f32 u, f32 len, f32 z, f32 H, u32 seed) {
  if (len <= 0 || z < 0 || z > H) return false;
  const f32 sdq = static_cast<f32>(seed % 997) / 997.0;
  const f32 floor_h = 3.1 + 0.5 * (static_cast<f32>((seed >> 12) % 1000) / 1000.0);
  const bool pil = !(u >= 0.38 && u <= len - 0.38);
  if (z < 4 && len > 3) {
    const f32 sp = 4.4, ns = std::fmax(1.0, std::floor(len / sp)), sm = (len - ns * sp) * 0.5;
    const f32 su = (u - sm) / sp - std::floor((u - sm) / sp);
    const bool in_s = u - sm >= 0 && u - sm <= ns * sp;
    return in_s && su >= 0.08 && su <= 0.92 && z >= 0.35 && z <= 3.0;
  }
  if (H >= 26) {
    const f32 fz = (z - 4) / floor_h - std::floor((z - 4) / floor_h);
    const f32 mu = u / 1.6 - std::floor(u / 1.6);
    return fz < 0.8 && mu < 0.95 && !pil;
  }
  const f32 pitch = 2.7 + (3.7 - 2.7) * fh(sdq * 7.0);
  const f32 n_win = std::fmax(1.0, std::floor((len - 0.8) / pitch)), margin = (len - n_win * pitch) * 0.5;
  const f32 lu = (u - margin) / pitch, fu = lu - std::floor(lu);
  if (lu < 0 || lu > n_win || z > H - 1.2) return false;
  const f32 fz = (z - 4) / floor_h - std::floor((z - 4) / floor_h);
  const f32 ww = 0.38 + (0.6 - 0.38) * fh(sdq * 5.0), wh = 0.42 + (0.6 - 0.42) * fh(sdq * 9.0);
  return fu >= 0.5 - ww * 0.5 && fu <= 0.5 + ww * 0.5 && fz >= 0.3 && fz <= 0.3 + wh;
}
void Marks::rebuild(const CityStream& city) {
  const Terrain& t = city.terrain();
  for (MeshData& g : ground_data_) g.clear();
  wall_data_.clear();
  constexpr i32 kSeg = 18;
  // Ground scorches (world_impacts.mjs SCORCH_FS): a ragged disc draped on the terrain, charred dark
  // in the middle (.012) to soot at the rim (.05), alpha .6 that fades out over the outer 30 % -
  // "softer than a painted disc: the ground still shows through at the rim". Kern has no per-vertex
  // alpha: the char and the two outer bands are three blended meshes (alpha .6 / .4 / .15).
  for (const Scorch& s : scorches_) {
    const f32 sd = static_cast<f32>(s.seed % 1000) / 100;
    auto at = [&](f32 x, f32 y) { return Vec3{x, y, t.height(x, y) + 0.16}; };
    auto ring_at = [&](f32 k, i32 i) {
      const f32 a = 2 * kPi * static_cast<f32>(i) / kSeg, rr = s.r * k * ragged(a, sd);
      return at(s.c.x + kern::math::cos(a) * rr, s.c.y + kern::math::sin(a) * rr);
    };
    auto char_col = [](f32 k) {  // mix(.05, .012, smoothstep(1, .35, k))
      const f32 u = clampf((1 - k) / 0.65, 0, 1), c = u * u * (3 - 2 * u);
      return Vec3{0.05, 0.045, 0.04} * (1 - c) + Vec3{0.012, 0.01, 0.01} * c;
    };
    auto band = [&](MeshData& g, f32 k0, f32 k1) {
      const u32 base = g.vertex_count();
      for (i32 i = 0; i < kSeg; ++i) g.push(ring_at(k0, i), {0, 0, 1}, char_col(k0), {});
      for (i32 i = 0; i < kSeg; ++i) g.push(ring_at(k1, i), {0, 0, 1}, char_col(k1), {});
      for (i32 i = 0; i < kSeg; ++i) {
        const u32 j = converted::rem((i + 1), kSeg), a0 = base + i, a1 = base + j, b0 = a0 + kSeg, b1 = a1 + kSeg;
        g.indices.insert(g.indices.end(), {a0, b0, b1, a0, b1, a1});
      }
    };
    MeshData& c = ground_data_[0];
    const u32 base = c.vertex_count();
    c.push(at(s.c.x, s.c.y), {0, 0, 1}, char_col(0), {});
    for (i32 i = 0; i < kSeg; ++i) c.push(ring_at(0.35, i), {0, 0, 1}, char_col(0.35), {});
    for (i32 i = 0; i < kSeg; ++i) c.indices.insert(c.indices.end(), {base, base + 1 + i, base + 1 + static_cast<u32>(converted::rem((i + 1), kSeg))});
    band(c, 0.35, 0.7);
    band(ground_data_[1], 0.7, 0.86);
    band(ground_data_[2], 0.86, 1.0);
  }
  // Wall marks in the wall's plane (dir along the wall, z up).
  auto wall_disc = [&](const WallMark& m, f32 inner, Vec3 c_in, f32 outer_k, Vec3 c_out, f32 seed) {
    const u32 base = wall_data_.vertex_count();
    const Vec3 n{m.n.x, m.n.y, 0};
    auto P = [&](f32 x, f32 y) { return m.c + Vec3{m.d.x * x, m.d.y * x, y}; };
    wall_data_.push(m.c, n, c_in, {});
    for (i32 i = 0; i < kSeg; ++i) {
      const f32 a = 2 * kPi * static_cast<f32>(i) / kSeg, e = ragged(a, seed);
      wall_data_.push(P(kern::math::cos(a) * m.size * inner * e, kern::math::sin(a) * m.size * inner * e), n, c_in, {});
    }
    for (i32 i = 0; i < kSeg; ++i) {
      const f32 a = 2 * kPi * static_cast<f32>(i) / kSeg, e = ragged(a, seed);
      wall_data_.push(P(kern::math::cos(a) * m.size * outer_k * e, kern::math::sin(a) * m.size * outer_k * e), n, c_out, {});
    }
    for (i32 i = 0; i < kSeg; ++i) {
      const u32 j = converted::rem((i + 1), kSeg), a0 = base + 1 + i, a1 = base + 1 + j, b0 = a0 + kSeg, b1 = a1 + kSeg;
      wall_data_.indices.insert(wall_data_.indices.end(), {base, a0, a1, a0, b0, b1, a0, b1, a1});
    }
  };
  for (const WallMark& m : soots_) {
    const f32 sd = static_cast<f32>(m.seed % 1000) / 100;
    const f32 k = 0.06 + 0.05 * (1 - m.level);
    wall_disc(m, 0.55, {0.015, 0.012, 0.01}, 1.0, {k, k * 0.86, k * 0.72}, sd);
  }
  for (const WallMark& m : breaches_) {
    const f32 sd = static_cast<f32>(m.seed % 1000) / 100;
    // facade_marks.mjs BREACH_FS: dark hole growing with the damage, broken concrete rim, cracks
    const f32 hole = 0.18 + 0.42 * m.level;
    const f32 g = 0.46 - 0.2 * m.level;
    wall_disc(m, hole, {0.035, 0.03, 0.028}, 0.82, {g, g * 0.96, g * 0.9}, sd);
    const Vec3 n{m.n.x, m.n.y, 0};
    Rng cr{m.seed | 1};
    const i32 cracks = 5 + static_cast<i32>(cr.next() % 5);
    for (i32 i = 0; i < cracks; ++i) {
      const f32 a = 2 * kPi * (static_cast<f32>(i) + cr.unit() * 0.7) / static_cast<f32>(cracks);
      const f32 r0 = m.size * hole * 0.9, r1 = m.size * (0.55 + 0.45 * cr.unit()) * (1.0 + 0.4 * m.level), wdt = m.size * 0.025;
      const Vec2 dir{kern::math::cos(a), kern::math::sin(a)}, side{-dir.y, dir.x};
      const u32 base = wall_data_.vertex_count();
      for (const Vec2 q : {dir * r0 + side * wdt, dir * r0 - side * wdt, dir * r1 - side * (wdt * 0.2), dir * r1 + side * (wdt * 0.2)})
        wall_data_.push(m.c + Vec3{m.d.x * q.x, m.d.y * q.x, q.y} + n * 0.002, n, {0.03, 0.028, 0.026}, {});
      wall_data_.indices.insert(wall_data_.indices.end(), {base, base + 1, base + 2, base, base + 2, base + 3});
    }
  }
  // facade_marks.mjs CRACK_FS: radial spokes, two broken rings, a tiny pit - light on the pane
  for (const WallMark& m : cracks_) {
    const Vec3 n{m.n.x, m.n.y, 0};
    Rng cr{m.seed | 1};
    auto line = [&](Vec2 a, Vec2 b, f32 w, Vec3 col) {
      const Vec2 d = b - a;
      const f32 l = std::fmax(1e-4, hypot_bp(d.x, d.y));
      const Vec2 s{-d.y / l * w, d.x / l * w};
      const u32 base = wall_data_.vertex_count();
      for (const Vec2 q : {a + s, a - s, b - s, b + s}) wall_data_.push(m.c + Vec3{m.d.x * q.x, m.d.y * q.x, q.y}, n, col, {});
      wall_data_.indices.insert(wall_data_.indices.end(), {base, base + 1, base + 2, base, base + 2, base + 3});
    };
    const Vec3 c{0.82, 0.86, 0.9};
    const i32 spokes = 7 + static_cast<i32>(cr.next() % 4);
    std::vector<Vec2> ends;
    for (i32 i = 0; i < spokes; ++i) {
      const f32 a = 2 * kPi * (static_cast<f32>(i) + (cr.unit() - 0.5) * 0.6) / static_cast<f32>(spokes);
      const f32 r = m.size * (0.6 + 0.4 * cr.unit());
      const Vec2 e{kern::math::cos(a) * r, kern::math::sin(a) * r};
      line(e * 0.08, e * 0.55, 0.004, c);
      line(e * 0.55, e, 0.003, c);
      ends.push_back(e);
    }
    for (std::size_t i = 0; i < ends.size(); converted::pre_inc(i)) {
      const Vec2 a = converted::at(ends, i), b = converted::at(ends, converted::rem((converted::plus(i, 1)), ends.size()));
      line(a * 0.35, b * 0.35, 0.003, c);
      if (cr.unit() < 0.7) line(a * 0.7, b * 0.7, 0.0025, c);
    }
    line({-0.01, 0}, {0.01, 0}, 0.01, {0.95, 0.97, 1.0});  // the pit
  }
}
void Marks::draw(WorldArt& art, const CityStream& city, World& w, f32 now) {
  if (dirty_ && struck_) {
    rebuild(city);
    Material m;
    m.alpha = AlphaMode::blend;
    m.color = {1, 1, 1, 0.88};
    m.roughness = 1;
    m.cast_shadow = false;
    m.double_sided = true;
    art.set_mesh(wall_mesh_, wall_data_, m);
    const f32 alphas[3] = {0.6, 0.4, 0.15};
    for (int k = 0; k < 3; ++k) {
      Material g = m;
      g.color = {1, 1, 1, converted::at(alphas, k)};
      art.set_mesh(converted::at(ground_mesh_, k), converted::at(ground_data_, k), g);
    }
    dirty_ = false;
  }
  for (const Chunk& c : rubble_) {
    if (!c.body.valid() || !w.body_valid(c.body)) continue;
    const physics::Pose p = w.pose(c.body);
    const f32 fade = clampf((c.until - now) / 2.5, 0, 1);
    art.put(art.cube, Mat4::trs(p.position, p.rotation, c.half * (2 * fade)), kRubbleColor);
  }
}
